vec2 calculateOffset(float size, float innerSize, float t) {
    if (iMouse.z>0.) {
        vec2 mpos = (iMouse.xy -.5* iResolution.xy) / iResolution.y;
        mpos += .5;
        mpos = mix(vec2(-1.),vec2(1.),mpos);
        return (size-innerSize) * mpos;
    }
    int i = int(t);
    t = fract(t)*2.-1.;
    return   ( size - innerSize )
           * (   i < 1 ? vec2(-1, -t)
               : i < 2 ? vec2( t, -1)
               : i < 3 ? vec2( 1,  t)
               :         vec2(-t,  1)
             );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = (fragCoord -.5* iResolution.xy) / iResolution.y;

    // Initialize color
    vec3 color = vec3(0.0);

    // Parameters
    float outerSize = 0.45;
    float thickness = 0.002;
    float t = mod(iTime, 4.0);

    // Draw squares
    //float currentSize = outerSize;
    vec2 absUV = abs(uv);
    float amt = 0.9;

    float blur = 1.5 / iResolution.y;

    for (int i = 0; i < 20; i++) {
        float currentSize = outerSize * pow(amt, float(i));
        float t = mod(iTime, 4.0);
        //float t = mod(iTime+float(i), 4.0);
        vec2 offset = calculateOffset(outerSize, currentSize, t);

        vec2 a = abs(uv - offset) - currentSize;
        //a = abs(absUV - offset) - currentSize;

        // Smooth outline for antialiasing
        float edge = abs(max(a.x, a.y));
        float border = smoothstep(thickness - blur, thickness + blur, edge);

        color = mix(color, vec3(1.0), 1.0 - border);
    }

    fragColor = vec4(color, 1.0);
}
